using System;
using System.Data;

// PROGRAM: Simulasi Pencegahan SQL Injection Menggunakan Parameterized Command
public class SecurityAuthenticationEngine
{
    public static void SimulateLogin(string username, string password)
    {
        Console.WriteLine($"Mencoba login dengan username: {username}");

        // Simulasi pemeriksaan parameterisasi
        if (username.Contains("'") || username.Contains("--"))
        {
            Console.WriteLine("[ANALISIS RAW CONCAT]: Terdeteksi injeksi karakter SQL berbahaya!");
        }

        // Dengan Parameterized Query: Nilai diperlakukan sebagai string literal utuh
        Console.WriteLine($"[PARAMETERIZED DB EXEC] Parameter @User='{username}' diperlakukan sebagai teks murni aman.");
        Console.WriteLine("Hasil: Percobaan bypass autentikasi SQL Injection GAGAL.\n");
    }
}

public class Program
{
    public static void Main()
    {
        SecurityAuthenticationEngine.SimulateLogin("budi", "password123");
        SecurityAuthenticationEngine.SimulateLogin("admin' --", "sembarang");
    }
}

