using System;
using System.Collections.Generic;
using System.Linq;

public class SqlBuilder
{
    public static string BuildSafeParameterizedQuery(string? tableName, string?[] columnNames)
    {
        if (string.IsNullOrWhiteSpace(tableName) || columnNames == null || columnNames.Length == 0)
            return "";

        var validCols = columnNames
            .Where(c => !string.IsNullOrWhiteSpace(c))
            .Select(c => c!.Trim())
            .ToList();

        if (validCols.Count == 0) return "";

        string colsStr = string.Join(", ", validCols);
        string paramsStr = string.Join(", ", validCols.Select(c => $"@{c}"));

        return $"INSERT INTO {tableName.Trim()} ({colsStr}) VALUES ({paramsStr})";
    }

    public static void Main()
    {
        string[] cols = { "Username", "Email", "Balance" };
        Console.WriteLine(BuildSafeParameterizedQuery("Users", cols));
    }
}
